quests[7633] = { id = 7633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Introduction", sourceObjective = "Your diligence and integrity has been noted, {class}.\n\nWe are Ancients: Protectors of this once great forest. Our physical forms were destroyed 10,000 years ago when Archimonde and the Burning Legion marched upon Hyjal. Our spirits, however, remain intact.\n\nThere are tasks that we can offer. Tasks that if completed will open up the secrets of the Ancients to you.\n\nKnow this, should you complete these tasks, merely return to this rock and we shall answer the calling.", sourceObjectiveStatus = "unverified-source-field" }
quests[7634] = { id = 7634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Sinew Wrapped Lamina", description = "Greetings, {class}. I am Hastat, Ancient of Lore. I hold knowledge lost eons ago.\n\nWith the proper binding, one of my leaves can serve as a quiver the likes of which has not been seen in 10,000 years. A quiver that when accompanied by a bow of Ancients, could grant untold powers.\n\nReturn here with sinew from an adult blue dragon and this quiver shall be yours.", sourceObjective = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood.", progress = "Welcome back, young {class}.", completion = "May my leaves provide your arrows protection from harm. May your arrows strike true. May the enemies of our world be smitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[7635] = { id = 7635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper String", description = "Vartrus may offer you the stave to create a bow of Ancients but only I can enchant the string required to complete the bow.\n\nIt is a simple task, puny one. Slay a mature black dragon and remove the sinew from its bones. Return that sinew to me and I shall enchant the material into an almost indestructible bow string.", sourceObjective = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood.", progress = "I am certain that you will have little difficulty in finding and slaying a black dragon, {name}. Do not waste my time with idle chatter.", completion = "A most foul dragon this one was. The sinew reeks of evil.\n\nGive me a moment to cleanse the filth from this flesh and apply the proper enchantments.", sourceObjectiveStatus = "unverified-source-field" }
quests[7636] = { id = 7636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stave of the Ancients", description = "Agents of the Burning Legion are still active in our world, {class}. These agents corrupt all that they touch. Nature wilts and weeps in their presence.\n\nYou must track down these demonic corrupters and destroy them, {name}. Be warned, you must engage them by yourself or they will flee. As long as you are alone, they will try and destroy you. You must strike at them, turning their arrogance into misery.\n\nI grant you a piece of my bark, the inscriptions shall lead you to your targets. Retrieve their heads.", sourceObjective = "You must find and destroy these four demonic corrupters:\n\nSimone the Seductress.\n\nKlinfran the Crazed.\n\nSolenor the Slayer.\n\nArtorius the Doombringer.\n\nDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\n\nRefer to the Petrified Bark in your inventory for clues as to their whereabouts.\n\nYou MUST complete this task by yourself.", progress = "Do not be fooled by their disguises!", completion = "You have served us well, {name}! Take this stave and combine it with the bow string that Stoma is able to create. Together, they form a most formidable weapon.", sourceObjectiveStatus = "unverified-source-field" }
quests[7637] = { id = 7637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emphasis on Sacrifice", description = "In order to prepare yourself for this task, you must first show due sacrifice and judgment... with an emphasis on sacrifice.\n\nYou must acquire High Priest Rohan's exorcism censer for your task.  Even though its use will be for good and just reasons, due compensation must be given for it.\n\nProceed to Ironforge and speak with the High Priest.  By bringing ample coin with you to help offset the loss of his censer, it will show your due sacrifice.\n\nGo now {name}, time is of the essence.", sourceObjective = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it.", progress = "Greetings, noble {class}!  I have prepared my trusted censer with the freshest of incense and blessed it thrice for your use.  Your donation will help us in Ironforge not only to create a new censer, but also to bolster sagging reserves of food for our needy.", completion = "Blessings onto you, friend {class}!  Your donation goes far beyond what was needed.  Your sacrifice will not only help us recover what we have lost, but also help us to help those most in need here in Ironforge.\n\nNow, let me make sure I've suitably prepared this censer for your future needs...", sourceObjectiveStatus = "unverified-source-field" }
quests[7638] = { id = 7638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Grayson Shadowbreaker", description = "The time has come, {name}, for you to learn about what it will take for you to acquire something you have no doubt waited on for some time... your charger.\n\nSpeak with Lord Grayson Shadowbreaker here in Stormwind's Cathedral District.  It is he who will guide you not only though the legerdemain of a Paladin's most trusted mount, but the tasks before you to acquire one of your own.\n\nI wish you the best in this trial.  For the Light, noble <brother/sister>!", sourceObjective = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District.", completion = "I am glad to see you {name}.  I know that you have awaited word as to how to acquire your charger, and now that time has come.\n\nYou will be surely tested in many different ways, but most importantly in your willingness to rise above numerous obstacles thrust before you.  These are not done as a learning exercise - your stature is beyond simple educational tests.  You must save your future companion from the clutches of the evil you have spent your life fighting.\n\nTake heed, your time has come!", sourceObjectiveStatus = "unverified-source-field" }
quests[7639] = { id = 7639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Show Due Judgment", description = "With my blessings, take the censer.  I myself have used it in several exorcisms, and it should serve you well for the arduous tasks that lie ahead.\n\nReturn now to Lord Grayson Shadowbreaker in Stormwind, {name}.  Your quest continues with him.", sourceObjective = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", progress = "Welcome back, {name}.  Have you acquired the exorcism censer?", completion = "Yes, this will do.  You will be called upon more than once during this process to make acts of sacrifice; I am glad to see that you are willing to do just that.  Sacrifice is a key component in what it takes to uphold the duties of being a {class}... but I don't have to lecture you on that.\n\nNow {name}, you will need to show due judgment in your actions.  To that end, this censer will act as your vessel to dispense such judgment on tortured spirits of lands lost to us.", sourceObjectiveStatus = "unverified-source-field" }
quests[7640] = { id = 7640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exorcising Terrordale", description = "I have added a pinch of dirt from the tainted ground of Terrordale in the Eastern Plaguelands to the censer.  You will now use this censer to find areas there that show signs of spiritual turmoil and disturbance.  Look for green auras that permeate the ground as the physical world buckles under the torment of the spirit realm and use the censer to drive out the evil spirits.\n\nWhen you have passed sufficient judgment on the spirits there, you will be ready to proceed.", sourceObjective = "Use the Exorcism Censer to drive out the spirits that torment Terrordale. When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", progress = "It is good to see you again {name}.  Is your work done in Terrordale?", completion = "Well done, {name}.  To render the judgment of the Light on those that dwell in darkness is a task we must approach with vim and zeal; you have done just that with your sacrifice in Ironforge and your judgments of the spirits in Terrordale.\n\nYour next steps will call on both sacrifice and judgment again as you now strive to reclaim the spirit of a fallen charger who now serves a Death Knight known as Darkreaver.", sourceObjectiveStatus = "unverified-source-field" }
quests[7641] = { id = 7641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Work of Grimand Elmore", description = "A paladin's charger is nothing more than a pack animal without proper barding for it.  The barding used by your charger not only needs to be of the finest materials possible, but because of the circumstances involved it must also be sufficiently attuned to the spirit realm.\n\nFirst things first, {name} - let's get your barding made.  In Stormwind's Dwarven District is one of the finest craftsmen living today, Grimand Elmore.  His work will not be cheap, but his quality is what we seek.  Speak with him.", sourceObjective = "Speak with Grimand Elmore in Stormwind's Dwarven District.", completion = "Hello there lad - Lord Shadowbreaker sent me word ahead of time that you'd be coming around this way to see me.  I'm willing to make the barding you need, but it won't be either cheap or easy; let's get that out in the open first and foremost.\n\nI will say this much, and Grayson will back me up when I make this claim... you'll not find better barding made anywhere in all of Azeroth than right here.", sourceObjectiveStatus = "unverified-source-field" }
quests[7642] = { id = 7642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collection of Goods", description = "You'll need four things for the barding - runecloth for the lining, arcanite bars for the plating, Arthas' Tears for the spiritual attunement, and Stratholme holy water for the spiritual imbuement.  Actually, you need five things... gold for my fee.  That fee includes all labor as well as a handcrafted saddle and stirrups.\n\nOnce you've got all that, I'll be able to finish your barding.  Until then, there are some things I can get started on for you while you assemble your collection of goods.", sourceObjective = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind.", progress = "Ah, {name}.  I won't be able to finish your barding without the things I mentioned.  Have you gotten everything together?", completion = "This... well, this is exactly what I needed.  You're quite the resourceful {class}, aren't you?\n\nAll right then, let's get this barding finished up for you!", sourceObjectiveStatus = "unverified-source-field" }
quests[7643] = { id = 7643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Equine Spirit", description = "Your barding needs a special form of blessing, one from an appropriate spirit.  In Dire Maul is such a spirit, the Ancient Equine Spirit.  It is currently held by a corrupt treant, Tendris Warpwood.  Pass judgment upon this foul beast, {name}.\n\nKnow this - freedom alone is not enough.  You must soothe the spirit before receiving its blessing.  For that, special horse feed is needed.  Travel to Southshore first and speak with Merideth Carlson on this... and prepare for more sacrifice.", sourceObjective = "Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food.\n\nTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it.", progress = "The Ancient Equine Spirit looks at you expectantly, as though it wants something from you.", completion = "The Ancient Equine Spirit accepts the offering of the Manna-Enriched Horse Feed, nuzzling the container as it helps itself to the special oats and grains.  After it has eaten a little, it looks at the barding you possess and positions itself as though it wants you to place it upon its back...", sourceObjectiveStatus = "unverified-source-field" }
quests[7644] = { id = 7644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessed Arcanite Barding", description = "As the barding rests on the back of the Ancient Equine Spirit, it glows ever so slightly.  The air is thick with power for a brief moment, and then the barding disappears from the back of the horse and is now secure in your backpack.\n\nIt would seem that the barding has been blessed.  As per Lord Shadowbreaker's instructions, you should now return with it to him in Stormwind.", sourceObjective = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", progress = "{name}, you're back!  Were you able to successfully deal with Merideth Carlson and Tendris Warpwood?  Honestly, I'm not sure which one is a greater threat at times...", completion = "You've come far, my friend.  Your barding is now suitably prepared for the last task at hand.\n\nYou will be using this barding to harness your charger once the task of redemption is complete.  Before that, however, you will have a monumental struggle to overcome.  Your time draws near - huzzah!\n\nThere is one last item that needs to be made before we begin this, {name}.  Hopefully your resourcefulness has not departed you since you had your barding made...", sourceObjectiveStatus = "unverified-source-field" }
quests[7645] = { id = 7645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manna-Enriched Horse Feed", description = "The Silver Hand thought me MAD when I told them that I could make a special horse feed that could nourish spiritual horses.  EVERYONE thought I was mad!  Well, now it's payback time!\n\nI'll make what you need, PALADIN... so-called CHAMPION... but it will cost you.  I need special biscuits - Enriched Manna Biscuits sold only by the Argent Dawn - for this blend.  I also demand, yes DEMAND gold as compensation for the misery I have endured!\n\nShow me the sacrifice you tout so much, PALADIN.", sourceObjective = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills. The Argent Dawn is known as the sole purveyor of the biscuits.\n\nYou also need to give her 50 gold to soothe her ruffled sensibilities.", progress = "Yes, I've proved you wrong now, haven't I?  I've proved them all wrong!  I WAS RIGHT ALL ALONG!!!", completion = "YES, NOW WHO - wait - you're giving me the gold too?  You weren't the one who called me mad (actually they called me a fruitcake nut-job)... still, you're willing to show sacrifice even for wrongs you've not committed?\n\nI... I misjudged you, {name}.  Should you need more horse feed, come see me.  I will give it to you free of charge.  Thank you... noble {class}.\n\nI am going to keep the money though - I'm not that much of a nut-job as to give up a fortune.", sourceObjectiveStatus = "unverified-source-field" }
quests[7646] = { id = 7646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Divination Scryer", description = "We now must assemble a Divination Scryer - this will begin the trial that will allow you to redeem the fallen charger.  Your scryer, actually, is almost done.  The exorcism censer used in Terrordale is the catalyst for it, and I will fashion a suitable housing for the device.\n\nThe last components needed, though, are two diamonds.  They must be as juxtaposed in brilliance as they are in purpose - an Azerothian and a Pristine Black.  These two will be the beacon by which the scryer will pierce the shadows!", sourceObjective = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", progress = "You have come so very far, {name}.  Your final act of worldly-item sacrifice will be the genesis for one of your greatest accomplishments.  I can feel it in the very fiber of my being!", completion = "These are fine specimens, {name} - the final pieces are now in place.  At long last, your time has come!\n\nIn the depths of the Great Ossuary of Scholomance are the skeletal remains of many beings.  Amongst them is a once-noble charger.  The hollowed soul of this charger now serves as the steed for Death Knight Darkreaver.  It is he whom you will face, and it is this steed that you will pass judgment upon.  Only you, {name}, can redeem its soul and save it from the torment of its servitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[7647] = { id = 7647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment and Redemption", description = "Take this satchel - in it are the items you will need for your task.\n\nUse the divination scryer in the heart of the Great Ossuary's basement to bring forth accursed spirits that must be judged.  Use your judgments wisely during this trial - they will prove more potent than you realize.  After the spirits, the death knight will appear; defeat him and reclaim the lost soul of the charger.  Only then {name}, will you be able to redeem it and place your barding upon your new steed!\n\nGood luck!", sourceObjective = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger.\n\nGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger.", progress = "The spirit of the fallen charger looks upon you with a mournful gaze.  Sad, almost hollow eyes look at you as though all hope was lost to it.", completion = "A glimmer of life - long vacant from the poor beast - shines in its eyes as you hand its judged soul back to it.  You feel a holy rush of power surge around you as you place the barding on its back, having judged the charger redeemed.  The charger nuzzles your hand as the burdens of the past are lifted from the beast.  You now feel as though you could call upon this beast to serve as your steed, should the need arise.\n\nYou have claimed your epic charger, {class}!  Congratulations!", sourceObjectiveStatus = "unverified-source-field" }
quests[7648] = { id = 7648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimand's Finest Work", description = "<Grimand wipes sweat from his brow, beaming with a sense of pride.>\n\nThere you are, my friend.  This is some of my finest work - as good as the barding I personally made for Lord Shadowbreaker when he went for his own charger.  I thank you for your trust in me to provide for you the best.\n\nNo doubt Grayson will want to see the work for himself as well.  Take your barding to him, and give him my thanks for his honorable business.", sourceObjective = "Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection.", progress = "You're progressing along nicely, {name}.  Once you have made your barding, you'll be well on your way to the next task.", completion = "This is most impressive work.  It seems that as Grimand gets older, his craftsmanship continues to improve.  That's quite the feat when his work was already some of the finest you'd find anywhere when he made my barding back in the day.\n\nWhile this barding would be a fine addition to any normal steed, we are not dealing with such a mundane beast.  You'll need this barding blessed by an appropriate source for it to be worthy of resting on a {class}'s charger.  I'll hold onto it for you until then.", sourceObjectiveStatus = "unverified-source-field" }
quests[7649] = { id = 7649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Thorium Platemail: Volume I", description = "The tome carries the mark of the Athenaeum.", sourceObjective = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Well done, my boy.\n\n<Lorekeeper Lydros tears out a page from the book.>\n\nI am sure you can make use of this recipe.", sourceObjectiveStatus = "unverified-source-field" }
quests[7650] = { id = 7650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Thorium Platemail: Volume II", description = "The tome carries the mark of the Athenaeum.", sourceObjective = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Well done, my boy.\n\n<Lorekeeper Lydros tears out a page from the book.>\n\nI am sure you can make use of this recipe.", sourceObjectiveStatus = "unverified-source-field" }
quests[7651] = { id = 7651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Thorium Platemail: Volume III", description = "The tome carries the mark of the Athenaeum.", sourceObjective = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Well done, my boy.\n\n<Lorekeeper Lydros tears out a page from the book.>\n\nI am sure you can make use of this recipe.", sourceObjectiveStatus = "unverified-source-field" }
quests[7652] = { id = 7652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Light Bargain", sourceObjective = "Aright, mister, I got a hot deal for ya.\n\nI'm lookin' to offload some of these here Imperial plate armor recipes and need someone willing to take on the burden. All I want in exchange is some thorium bars. Sound good?", sourceObjectiveStatus = "unverified-source-field" }
quests[7653] = { id = 7653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Plate Belt", progress = "For the belt plans, I'll be needin' 20 thorium bars.", completion = "A pleasure doin' business with ya.\n\nAnd {name}, wipe that look of disgust off yer face." }
quests[7654] = { id = 7654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Plate Boots", progress = "For the boot plans, I'll be needin' 40 thorium bars. Yep, 40. Are you gonna cry? Would you like a hanky?\n\n<Derotain laughs.>", completion = "A pleasure doin' business with ya.\n\nAnd {name}, wipe that look of disgust off yer face." }
quests[7655] = { id = 7655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Plate Bracer", progress = "For the bracer plans, I'll be needin' 20 thorium bars.\n\nAre you alright, sonny? Yer getting' all red.", completion = "A pleasure doin' business with ya.\n\nAnd {name}, wipe that look of disgust off yer face." }
quests[7656] = { id = 7656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Plate Chest", progress = "For the chest piece plans, I'll be needin' 60 thorium bars.\n\nOh boy, there you go again. Are you gonna be runnin' to yer blue Gods, askin' why they have forsaken you?!? Toughen up, Nancy! Nobody ever said life's fair.", completion = "A pleasure doin' business with ya.\n\nAnd {name}, wipe that look of disgust off yer face." }
quests[7657] = { id = 7657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Plate Helm", progress = "Just hand over 50 thorium bars and the helm plans are yers.", completion = "A pleasure doin' business with ya.\n\nAnd {name}, wipe that look of disgust off yer face." }
quests[7658] = { id = 7658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Plate Leggings", progress = "Just hand over 60 thorium bars and the leg plans are yers.\n\nI know, I'm driving you into bankruptcy! I've heard it all before so you can save your sob story, weakling.", completion = "A pleasure doin' business with ya.\n\nAnd {name}, wipe that look of disgust off yer face." }
quests[7659] = { id = 7659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Plate Shoulders", progress = "For the shoulder plans, I'll be needin' 20 thorium bars.", completion = "A pleasure doin' business with ya.\n\nAnd {name}, wipe that look of disgust off yer face." }
