quests[7665] = { id = 7665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red Raptor Replacement" }
quests[7666] = { id = 7666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Again Into the Great Ossuary", sourceObjective = "Are you headed back into the Scholomance, {name}?  You've already paid such a great price for the use of the Divination Scryer - perhaps you'd like to take another one with you.  With it, you'd be able to face the perils of the Great Ossuary once more.\n\nBy all means, have it.  You've certainly earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[7667] = { id = 7667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Material Assistance", description = "{name}, there is a pressing matter I hope you can help with... both materially and spiritually.  Allow me to explain.\n\nWithin the depths of the Scholomance in Lordaeron is a chamber called the Great Ossuary.  I need to complete a device that would pierce the shadows of this horrid room.  To finish what I have started, I need two diamonds: an Azerothian and a Pristine Black.  These are not trivial items, I know - I just don't have the resources myself.\n\nCould you provide me with one of each?", sourceObjective = "If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond.", progress = "I feel awkward asking for material assistance, but my divination scryer - the device I hope to finish - requires one of each.  If you cannot help me, I'd certainly understand.", completion = "Your generosity is unrivaled, {name}.  I thank you for your kindness.\n\nI will be able to finish my divination scryer now, and I should be able to fashion more without further need of diamonds... perhaps you would be interested in helping me in its use?  It is for a most important task, I assure you... one that left unchecked could spell unmitigated disaster for the spirit realm!", sourceObjectiveStatus = "unverified-source-field" }
quests[7668] = { id = 7668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkreaver Menace", description = "Death Knight Darkreaver lords over the Great Ossuary in the Scholomance.  He threatens to twist the spirit realm to do his own bidding, and he must be stopped!  This is where the scryer you helped make comes into play.\n\nUse the divination scryer in the heart of the Great Ossuary's basement to call forth Darkreaver's spirit minions.  Defeat the spirits and the death knight himself will appear.  {name}, bring me his head!  Only his demise will reverse the damage dome to the spirit realm!", sourceObjective = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.\n\nBring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.", progress = "Time is critical, {name} - have you succeeded in stopping Death Knight Darkreaver's threat?", completion = "This is a victory to savor, {name}!  The demise of Darkreaver should restore the fragile fetters that anchor the spirit realm.\n\nYou have far exceeded what was asked of you, even when you had no notion of reward or compensation.  You are truly a {class} of worth, my friend.\n\nI know that acting to preserve the spirit realm should be thanks enough, but please - accept this simple gift with my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[7669] = { id = 7669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Again Into the Great Ossuary", sourceObjective = "Are you headed back into the Scholomance, {name}?  You've already paid such a great price for the use of the Divination Scryer - perhaps you'd like to take another one with you.  With it, you'd be able to face the perils of the Great Ossuary once more.\n\nBy all means, have it.  You've certainly earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[7670] = { id = 7670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Grayson Shadowbreaker", description = "The time has come, {name}, for you to learn about what it will take for you to acquire something you have no doubt waited on for some time... your charger.\n\nSpeak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District.  It is he who will guide you not only though the legerdemain of a Paladin's most trusted mount, but the tasks before you to acquire one of your own.\n\nI wish you the best in this trial.  For the Light, noble <brother/sister>!", sourceObjective = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District.", completion = "I am glad to see you {name}.  I know that you have awaited word as to how to acquire your charger, and now that time has come.\n\nYou will be surely tested in many different ways, but most importantly in your willingness to rise above numerous obstacles thrust before you.  These are not done as a learning exercise - your stature is beyond simple educational tests.  You must save your future companion from the clutches of the evil you have spent your life fighting.\n\nTake heed, your time has come!", sourceObjectiveStatus = "unverified-source-field" }
