quests[7828] = { id = 7828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalking the Stalkers", description = "Many brave trolls have been lost to the harsh wilds of the Hinterlands, {race}. The Silvermane wolves are one of the biggest threats to our hunters. They lay in wait, hiding amongst the bushes and landscape, then strike out when the opportunity presents itself.\n\nThis type of ferocity will not go unchecked!\n\nYou must think like the Silvermane. Stalk the stalkers! Slay them all!", sourceObjective = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 15 Silvermane Stalkers and 15 Silvermane Howlers. Return to him once the task is complete.\n\nMarkhor mentioned that the wolves hide in the wilds of the Hinterlands.", completion = "A job well done, {race}. The Revantusk thank you for your contribution.", sourceObjectiveStatus = "unverified-source-field" }
quests[7829] = { id = 7829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt the Savages", description = "Among the more ornery of the wildlife of the Hinterlands are the savage owlbeasts. Many a good Revantusk warrior has been lost to the ferocious claws and beak of the beasts.\n\nKill every savage owlbeast you see, {race}. Return to me when you can stand no more bloodshed. Your contribution will then be weighed, measured, and judged.", sourceObjective = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 20 Savage Owlbeasts. Return to him once the task is complete.\n\nMarkhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands.", completion = "You have proven a worthy ally to the Revantusk, {name}. Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[7830] = { id = 7830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenging the Fallen", description = "The filth that calls itself Wildhammer trains gryphon to slay troll. Horrible, I know, but worry not, justice will soon be meted out.\n\nFor now, I want you to focus on eradicating the elder gryphons of the region. They are known as Skylords.\n\nSlay one and return to me with its plume.", sourceObjective = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete.\n\nMarkhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands.", progress = "The Razorbeak Skylord is a much rarer breed of gryphon: One responsible for mating and creating murderous offspring.", completion = "<Markhor examines the plume.>\n\nI wonder how many of our hunters this beast devoured before you brought it to justice.", sourceObjectiveStatus = "unverified-source-field" }
quests[7831] = { id = 7831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Donation of Mageweave", progress = "Mageweave is running low, and we could use your help to replenish our stocks!  By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal.  Such generosity would not go unnoticed by Orgrimmar, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful!  We thank you for your generous donation, {name}!" }
