quests[7936] = { id = 7936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "50 Tickets - Last Year's Mutton", progress = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", completion = "Here you go, here you go!  A prize fit for a king!  Congratulations to you, my friend!\n\nIf you have more tickets you'd like to turn in, then please let me know!  For as long as the Darkmoon Faire is here, I'll redeem your tickets." }
quests[7937] = { id = 7937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Fortune Awaits You...", description = "\"Your fortune awaits you in Eastvale.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Eastvale Logging Camp in Elwynn Forest.  Focusing closer in on the image, you see a haystack that sits next to a stable.", sourceObjective = "Travel to the Eastvale Logging Camp in Elwynn Forest and seek out your fortune.", progress = "This haystack looks like the one from your vision.", completion = "A quick search of the haystack reveals a lockbox from within it!  It would seem that you have found your fortune!", sourceObjectiveStatus = "unverified-source-field" }
quests[7938] = { id = 7938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Fortune Awaits You...", description = "\"Your fortune awaits you inside the Deadmines.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Deadmines inside Westfall's ruined hamlet of Moonbrook.  Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the mines itself.  Stepping through it, a strange chest appears out from nowhere.", sourceObjective = "Travel to the Deadmines in Westfall and seek out your fortune.", progress = "This chest looks like the one from your vision...", completion = "A quick search of the chest reveals a lockbox from within it!  It would seem that you have found your fortune!", sourceObjectiveStatus = "unverified-source-field" }
quests[7939] = { id = 7939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Dense Grinding Stones", progress = "{name}, thank you for all the help you've given me.  I really can't thank you enough!\n\nAlthough my need is no longer great... if you bring me more dense grinding stones, I still have more Darkmoon Faire tickets for you.", completion = "Again, thank you {name}.  Please enjoy these tickets, and tell your friends about the Darkmoon Faire!" }
quests[7940] = { id = 7940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "1200 Tickets - Orb of the Darkmoon", progress = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", completion = "Here you go, here you go!  A prize fit for a king!  Congratulations to you, my friend!\n\nIf you have more tickets you'd like to turn in, then please let me know!  For as long as the Darkmoon Faire is here, I'll redeem your tickets." }
quests[7941] = { id = 7941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Armor Kits", progress = "{name}, I must thank you for all your help.  I have plenty of supplies, through no small efforts on your part, but if you wish to bring me more armor kits, then I will gladly trade them for Darkmoon Faire tickets.", completion = "There you are, {name}.  A fair trade.  Enjoy." }
quests[7942] = { id = 7942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Thorium Widgets", progress = "{name}, you have been so good to us, bringing me goods without tiring.  You have my eternal thanks!\n\nAlthough our need for Thorium widgets is not as great as it was, you may still bring them to me and I will gladly trade them for Darkmoon Faire tickets.", completion = "Here you are, {name}.  Here are Darkmoon Faire tickets for your enjoyment.  Do not, as they say, spend them all in one place!" }
quests[7943] = { id = 7943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Bat Eyes", progress = "{name}, the attraction I'm designing will be the scariest event since Gnomeregan was overrun!  And it's largely thanks to you and all the baubles you've brought me.  Many, many thanks!\n\nI don't need much else, but... if you bring me more evil bat eyes from the bats of the Eastern Plaguelands... I might have more Darkmoon Faire tickets for you.", completion = "Thanks again, {name}.  Here are your tickets!" }
quests[7944] = { id = 7944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Fortune Awaits You...", description = "\"Your fortune awaits you inside Wailing Caverns.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of a cave to the southwest of the Crossroads in the Barrens.  Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the caverns itself.  Stepping through it, a strange chest appears out from nowhere.", sourceObjective = "Travel to the Wailing Caverns in the Barrens and seek out your fortune.", progress = "This chest looks like the one from your vision...", completion = "A quick search of the chest reveals a lockbox from within it!  It would seem that you have found your fortune!", sourceObjectiveStatus = "unverified-source-field" }
quests[7945] = { id = 7945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Fortune Awaits You...", description = "\"Your fortune awaits you outside Palemane Rock.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Palemane Rock of Mulgore.  Focusing closer in on the image, you see a tree stump that sits close to the cave entrance.", sourceObjective = "Travel to Palemane Rock in Mulgore and seek out your fortune.", progress = "This tree stump looks like the one from your vision.", completion = "A quick search of the tree stump reveals a lockbox from within it!  It would seem that you have found your fortune!", sourceObjectiveStatus = "unverified-source-field" }
quests[7946] = { id = 7946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spawn of Jubjub", progress = "I'm so happy Jubjub is no longer lost.  She loves Dark Iron ale so much that when I ran out... she ran away to find more!\n\nNow that Jubjub's back, I want as much ale as I can get!  I won't want her to run away again!\n\nDo you have any Dark Iron Ale?  If you do, then I'll trade you one of Jubjub's frog eggs for a mug...", completion = "Thank you, {name}.  Here is your egg!  It won't be ready to hatch for a little while, but when it does you'll have a great pet!" }
quests[7961] = { id = 7961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waskily Wabbits!", description = "These rabbits are breeding uncontrollably.  Something must be done!\n\nHelp us {name}, you're our only hope.", sourceObjective = "Kill 5 rabbits and return to Jon LeCraft by the forge on Designer Island.", sourceObjectiveStatus = "unverified-source-field" }
quests[7962] = { id = 7962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wabbit Pelts", description = "I want LeCrafty rabbit pelts.  Get me some from LeCrafty Rabbits.\n\nThis is important!", sourceObjective = "Bring 3 LeCrafty Rabbit Pelts to Jon LeCraft.", sourceObjectiveStatus = "unverified-source-field" }
quests[7981] = { id = 7981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "1200 Tickets - Amulet of the Darkmoon", progress = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", completion = "Here you go, here you go!  A prize fit for a king!  Congratulations to you, my friend!\n\nIf you have more tickets you'd like to turn in, then please let me know!  For as long as the Darkmoon Faire is here, I'll redeem your tickets." }
