quests[8041] = { id = 8041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of Mount Mugamba", sourceObjective = "Hail, {class}. I am Jin'rokh the Breaker, troll of Mugamba. We of the Zandalar tribe recognize your accomplishments. We salute your tenacity and strength of will.\n\nWear this talisman around your neck, {class}. Let the strength of Mount Mugamba flow through your being. Be empowered as you strike down our enemies!", sourceObjectiveStatus = "unverified-source-field" }
quests[8042] = { id = 8042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of Mount Mugamba", progress = "It is good to see you in good health, {name}. The glorious battles you have undertaken affect all life on this planet. Hakkar must never leave the confines of Zul'Gurub as the world will surely collapse beneath his immense hunger.\n\nGive me your talisman and I shall amplify its strength. Use the Strength of Mugamba to punish our enemies!", completion = "Our paths will cross again, {class}." }
quests[8043] = { id = 8043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of Mount Mugamba", progress = "Master {name}, you return! Molthor has sent word of your deeds to the King. Your name is known even in the South Seas. Perhaps one day you will be a legendary {class} - a story for the ages.\n\nGive me your talisman so that I may once more amplify its power.", completion = "Use your newfound strength to destroy the Gurubashi!" }
quests[8044] = { id = 8044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rage of Mugamba", progress = "King Rastakhan sends his regards, Master {name}. Such an honor has never been given to one outside the Zandalar tribe.\n\n\n\nGive me your talisman so that I may enhance it once more. Know that the Rage of Mugamba is now intrinsically connected to your very soul.", completion = "Zul'jin would be envious, {class}. Go forth and conquer!" }
quests[8045] = { id = 8045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heathen's Brand", sourceObjective = "Know this, heathen: A catastrophe has brought us together. Your pagan ways are neither understood nor appreciated by Zandalar but we are a fair people. Wear this brand around your neck. It shall serve as both a warning to our enemies and a symbol of your friendship to Zandalar.\n\nContinue to serve our people and I will amplify the power of the brand.", sourceObjectiveStatus = "unverified-source-field" }
quests[8046] = { id = 8046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heathen's Brand", progress = "I may have been too hasty in my judgement, {class}. It seems as if your blind faith in this Light has some value after all.\n\nGive me your brand and I shall amplify its power.", completion = "Do what you must to defeat our enemies, {class}. Even if it means channeling the Light." }
quests[8047] = { id = 8047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heathen's Brand", progress = "I must confess, I did not think you had the resolution to see this cause through, {class}. Zandalar now considers you an invaluable ally. Well done, indeed.\n\nGive me your brand and I shall once more amplify its power.", completion = "Our beliefs differ but our cause is righteous. Strike down our foes, noble {class}." }
quests[8048] = { id = 8048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hero's Brand", progress = "The King has acknowledged your existence, {class}. You are the first of your kind to be accepted by Rastakhan as a true ally of Zandalar.\n\nYou will be rewarded greatly for your efforts. Present your brand and I shall apply the final amplification.", completion = "Vigilance, honor, loyalty, bravery... You embody all of these traits and so shall your brand." }
quests[8049] = { id = 8049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Zuldazar", sourceObjective = "Accept this talisman as a token of our appreciation, {class}.\n\nThe Eye of Zuldazar will grow in power as your bond with the trolls of Zandalar strengthens. Return to me periodically and I shall imbue the jewel.", sourceObjectiveStatus = "unverified-source-field" }
quests[8050] = { id = 8050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Zuldazar", progress = "Welcome {class}. The Eye of Zuldazar pulses with energy. You are ready to take the next step. Hand me the talisman and I shall perform the imbue.", completion = "Continue in your battle against the Soulflayer and his minions, {name}. He must never be permitted to leave the confines of Zul'Gurub." }
quests[8051] = { id = 8051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Zuldazar", progress = "Tales of your battles against the Gurubashi are whispered in the winds, {class}. Even royalty is beginning to talk of your deeds. It is rumored that King Rastakhan even mentioned you by name.\n\nThe time has come to imbue the Eye. Hand me the talisman and I shall perform the service.", completion = "Be resolute in your endeavors, {name}. The Soulflayer will attempt to siphon your will to live." }
quests[8052] = { id = 8052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The All-Seeing Eye of Zuldazar", progress = "If only we had ten-thousand more like you, {name}. The armies of Hakkar would be scattered to the wind in the blink of an eye.\n\n\n\nAlas, the Eye is ready to realize its full potential. Give it to me.", completion = "Smite them all and let Hakkar sort them out..." }
quests[8053] = { id = 8053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Freethinker's Armguards", description = "You are a heathen.  Heathens have a place in the tribe.  Heathens are freethinkers of Zandalar.  Freethinkers do not fear oppression.  Freethinkers die for what they believe in.  We know you would die for what you believe in.  This earns our acknowledgement.  This earns you a chance to prove yourself further.\n\nWe must have the Paragons of Power.  Go to Zul'Gurub.  Kill the minions of Hakkar.  Return when you have what I seek.  Claim the first battle gear of a Zandalar freethinker.\n\nGo.", sourceObjective = "Bring Jin'rokh the BreakerPrimal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", progress = "You have returned?  Do you have the Paragons of Power?  Are you wasting my time?\n\nI hope not, heathen.", completion = "You do much to honor us.  Your hands drip with the blood of Hakkar's minions.  You are a friend to the tribe.\n\nWear these bracers.  They are the freethinker's armguards.  This is what I mean about real power.", sourceObjectiveStatus = "unverified-source-field" }
quests[8054] = { id = 8054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Freethinker's Belt", description = "Your beliefs are alien to us, heathen.  Ancient Zandalar were once branded as heretics.  This was when the Gurubashi Empire was strong.  Heathens dared to challenge the priest of Hakkar.  Heathens then were hunted and killed as vermin.  Those heathens never wavered in their fight against the Blood God.  We honor the price they paid.  They are the freethinkers.\n\nDestroy the minions of Hakkar in Zul'Gurub.  Bring me the Paragons of Power I seek.  Success will be greatly rewarded.\n\nGo.", sourceObjective = "Bring Jin'rokh the Breaker a Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", progress = "Your presence means victory?  Do you have the Paragons?  Are you dripping in the remains of your enemies?", completion = "Your honor is assured in the tribe.  You claim many deaths in Zul'Gurub.  Enemies fall before your convictions.  Enemies fall before your power.\n\nThis is the freethinker's belt.  It is a symbol of honor.  It is powerful mojo.  It is now yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[8055] = { id = 8055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Freethinker's Breastplate", description = "Battle gear gives you power in the tribe.  The freethinkers are honored in this way.  They are zealots.  They imbue their breastplates with powerful mojo.  If their beliefs falter in the face of the enemy, their breastplate will not.\n\nYou must be revered amongst us to possess such a breastplate.  Go to Zul'Gurub.  Take the Paragons of Power I need.  Take the Paragons most painfully from the fools inside.  Bring them to me.  Prove your worth as a freethinker once and for all.", sourceObjective = "Bring Jin'rokh the Breaker a Primal Hakkari Tabard. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", progress = "Do you have the Paragons?  They have mojo inside them.  We must have them.  You will aid us.", completion = "You have done what few ever could.  You have brought the minions of Hakkar to their knees.  You have shown them what a freethinker can do.  You have shown us how a heretic could be revered in the tribe.  You have more than real power.  You ARE real power.\n\nTake the breastplate, freethinker.  Crush those who oppose you.", sourceObjectiveStatus = "unverified-source-field" }
quests[8056] = { id = 8056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Augur's Bracers", description = "The augurs of our tribe are revered for their gifts of the divine sight, ya mon.  They ain't a witch doctor; they spend their time castin' bones or readin' the leaves for insight - not hexin' people.  As a shaman, you already know somethin' about the power of augury; we Zandalar prize the insight they give to the tribe.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this for us, and I'll give ya some bracers that our augurs prize above all others!", sourceObjective = "Bring Maywiki of Zuldazar a Primal Hakkari Armsplint. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.", progress = "Got the Paragons of Power from Zul'Gurub that I need?  These bracers are well worth any effort ya be needin' to make!", completion = "It seems ya got a bit of the Zandalar augur in ya.  We know about the deeds you've been doin' in Zul'Gurub on our behalf mon.  These Paragons of Power will go a long way to helpin' out the Zandalar tribe - a tribe, I might add, ya can call upon as friends.  Take these bracers, {name}; ya earned them and then some!", sourceObjectiveStatus = "unverified-source-field" }
quests[8057] = { id = 8057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Haruspex's Bracers", description = "A haruspex is a key member of our tribe; you'll be wise to listen to their portents.  By communion with animals and givin' them up to the spirits when needed, they give us divine guidance.  In times past, the haruspex's insight and wisdom gave us an edge in the wars against the splintered tribes of the Gurubashi.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this, and I'll give ya bracers that any haruspex of the Zandalar would want.", sourceObjective = "Bring Maywiki of Zuldazar a Primal Hakkari Stanchion. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.", progress = "Have ya got the Paragons of Power from Zul'Gurub?  These bracers are worth the effort, {name}.  Trust me mon!", completion = "Ah, I can sense the power comin' from these Paragons of Power, {name}.  Ya proved to be someone we in the tribe can call \"friend.\"  A deal is a deal, {name}... behold the power of the haruspex's bracers!", sourceObjectiveStatus = "unverified-source-field" }
quests[8058] = { id = 8058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Vindicator's Armguards", description = "Vengeance is power.  The Zandalar vindicator is such power.  The tribe has many enemies.  The vindicator exacts retribution on them.  No crime against us is unpunished.  The vindicator delivers this punishment.  Our enemies fear our vengeance.  They should.  They forever will.\n\nBecome one of our vindicators.  Seek the Paragons of Power inside Zul'Gurub.  Slay the minions of Hakkar and claim vengeance in the tribe's name.  You will be rewarded.", sourceObjective = "Bring Jin'rokh the Breaker a Primal Hakkari Armsplint. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", progress = "Have you brought the Paragons of Power?  Has vengeance been claimed in the name of the Zandalar?", completion = "You have wrought much vengeance today.  You have taken on the visage of the vindicator.  You have brought the Blood God's minions to their knees.\n\nTake this.  It will fuel your vengeance for the future.  You are a friend to the Zandalar now.", sourceObjectiveStatus = "unverified-source-field" }
quests[8059] = { id = 8059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Demoniac's Wraps", description = "Warlocks tread dangerous ground in dealing with demons, but our demoniacs take this one step further.  Through an ancient and arcane ritual, they allow a demon to enter their being.  Rather than let it possess them though, they enslave the demon from the inside, absorbing the power of the beast for their own command.  It is a feat few are ever able to master.\n\nFor you to learn of the power of the demoniac, I must have Paragons of Power from Zul'Gurub.  Go there and retrieve that which we seek.", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Stanchion. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "Have you returned with the Paragons of Power?  By defeating the diabolic minions of the Hakkar, you will not only prove yourself to us, but also your willingness to learn the ways of the demoniac.", completion = "Well done... no doubt they were made to pay in excruciating ways before they gave up the Paragons of Power.  Take this - the demoniac's wraps.  Made from powerful mojo used in summoning the demoniac's prey, it is a powerful tool in your acquisition of power.", sourceObjectiveStatus = "unverified-source-field" }
quests[8060] = { id = 8060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Illusionist's Wraps", description = "Mages in our tribe are known as illusionists.  They employ powerful mojo in their incantations, often befuddling and confusing the tribe's enemies!\n\n<Al'tabim laughs wickedly.>\n\nIt is quite the sight to see a powerful illusionist at work, bringing our enemies to their knees from their own madness!\n\nFor you to know the way of our illusionists, go to Zul'Gurub and bring back to me selected Paragons of Power.  For this, I will give you arm wraps our illusionists use to weave their spells.", sourceObjective = "Bring Al'tabim the All-SeeingPrimal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "{name} - you've returned already?  Were you able to get the Paragons of Power I need?", completion = "Impressive... could you feel the mojo flowing through them?  The Paragons of Power were used as currency of sorts back when the Gurubashi Empire ruled these lands.  Now we Zandalar will use the latent mojo inside of them to fight the second rise of the Blood God Hakkar!\n\nYou've done well today - consider yourself to have a friend in the Zandalar.  For that, here are the illusionist's wraps I promised!", sourceObjectiveStatus = "unverified-source-field" }
quests[8061] = { id = 8061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Confessor's Wraps", description = "We Zandalar invest power in those who speak with the authority of divinity.  Our priests are more than just healers - they are our confessors.  Evil comes both from outside threats - such as Hakkar - and from within the tribe.  Our confessors act as the judges amongst us, preserving us from the same evil that devoured the Gurubashi from inside itself.\n\nGo to Zul'Gurub and bring back the Paragons of Power from the Gurubashi.  Learn what it means to be the confessor, and preserve us from evil.", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Stanchion. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "Back from Zul'Gurub, are you?  Have you succeeded in retrieving the Paragons of Power from the minions of Hakkar?", completion = "Outstanding, {name}!  This was no small feat bringing these to me.  No doubt you've acted as our tribe's confessor today in preserving ourselves against the threat of Hakkar.  These wraps are befitting a friend of the tribe such as you!", sourceObjectiveStatus = "unverified-source-field" }
quests[8062] = { id = 8062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Predator's Bracers", description = "In the dark times after the fall of the Gurubashi Empire, Zandalar predators used their prowess to provide sustenance for the tribe.  Hunters claim to be much like our tribe's predators - to seek the hunt is to embody the essence of the predator, yes.  Your hunt in Zul'Gurub, however, will show us how you truly rate amongst our finest predators.\n\nBring to me a sampling of the Paragons of Power from within Zul'Gurub.  Do so, and you'll take first steps in becoming the penultimate predator.", sourceObjective = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", progress = "Hunt those in Zul'Gurub that would possess the Paragons of Power, {name}.  They are your prey; they possess that which we both must have.", completion = "Yes... I need no vision to sense the presence of the Paragons of Power.  Your success in Zul'Gurub has impressed many among the tribe.  We not only consider you to be a friend of the Zandalar, but also consider you worthy enough to possess the predator's bracers - powerful items, and a symbol of what it means to be a predator.  Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8063] = { id = 8063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Madcap's Bracers", description = "The madcaps of Zandalar are similar to rogues, but above all else they embrace madness... chaos... the unpredictability of existence.  A terror to behold on the battlefield, they sowed the seeds of confusion and mayhem amongst our enemies in the savage times after the tribes splintered.  We would not be here today without them.\n\nBring to me the Paragons of Power from Zul'Gurub that I seek, and I will grant you the first of the madcap's prized armors.  Embrace the madness!", sourceObjective = "Bring Falthir the Sightless a Primal Hakkari Armsplint. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", progress = "Seek the madness from within Zul'Gurub and overshadow it with your own, {name}!  To do so means success, and success means reward!  Let not the Blood God reign supreme again!", completion = "Well done, {name}... your accomplishments in Zul'Gurub have earned you the right to call the Zandalar tribe as a friend.  I will see to the disposition of the Paragons; for your effort please accept this reward!", sourceObjectiveStatus = "unverified-source-field" }
quests[8064] = { id = 8064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Haruspex's Belt", description = "We Zandalar know not of druidic ways; nature is to be shaped by our need, not the other way around.  Still, a haruspex is the one of us most in tune with nature, and rightly so.  To give up the ghost of a beastie is to know what it is to be one of them.  That is the real power of nature.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub, proving yourself to us.  Do this, and I'll give ya a powerful item - a belt used by many of the Zandalar's haruspices.\n\nStrong mojo, ya mon!", sourceObjective = "Bring Maywiki of Zuldazar a Primal Hakkari Sash. Maywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale. You must also be Honored with Zandalar.", progress = "Got the Paragons of Power from Zul'Gurub I need?  The haruspex's belt will be yours if ya have them.", completion = "I thank you - the latent power in these items will be treasures unto themselves, you betcha.  Not only have ya done as I've asked of ya, but you've also proven to be honorable to us here in the tribe.  As promised, here is your reward!", sourceObjectiveStatus = "unverified-source-field" }
quests[8065] = { id = 8065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Haruspex's Tunic", description = "The ultimate symbol of a haruspex's power is what they wear, {name}.  Of these, the tunic symbolizes the connection between themselves and the divine wisdom they seek.  It often weaves parts of the beasties they sacrifice into the tunic; this reminds them of the connection they have to their gifts.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this, and a tunic seeping with the true power of a haruspex is yours.", sourceObjective = "Bring Maywiki of Zuldazar a Primal Hakkari Tabard. Maywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale. You must also be Revered with Zandalar.", progress = "Got the necessary Paragons of Power from Zul'Gurub?  The haruspex's tunic is well worth any effort ya be needin' to make.", completion = "Impressive... you've successfully collected the required Paragons of Power, {name}.  Your accomplishments in Zul'Gurub for the Zandalar are legendary; hence forth, you'll be revered amongst the tribe.  Here is your tunic, mighty {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8066] = { id = 8066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Predator's Belt", description = "A predator knows how to stalk their prey, but a successful one knows how to strike at it once they have closed ranks.  You must master both to have any chance of success in Zul'Gurub... and any chance of being like the Zandalar predators.\n\nBring me choice parts of the Paragons of Power from within Zul'Gurub.  My reward will be the power that the trinkets yield, while yours will be the Zandalar predator's belt - equipment well worth the trade.", sourceObjective = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", progress = "Strike at the insane minions of Hakkar in Zul'Gurub - they are the ones that hold the Paragons of Power, {name}.  Prove your success to them - and to the tribe - as an aspirant to the predator.", completion = "I sensed your arrival moments before, {name}, but none too easily.  What revealed yourself to me were the Paragons of Power you brought.  I can feel the power without needing to see the trinkets; their latent mojo - raw magic, if you will - will continue to fuel our efforts of vanquishing the diabolic schemes of the Blood God Hakkar.\n\nYou are to be commended - and rewarded - for your success.  You are honored amongst the tribe, and you are worthy to wear the predator's belt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8067] = { id = 8067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Predator's Mantle", description = "We Zandalar prize what we wear as a symbol of accomplishment.  You don't need to be able to see what one wears to be able to sense what emanates from it - power transcends sight.  The garments of the Zandalar predator are like this, and most cherished by them is the mantle they wear.  It helps to obfuscate them from view... and to make their presence known when they wish it.\n\nThe Paragons of Power await your retrieval in Zul'Gurub.  Bring me what I seek, and the predator's mantle shall be yours.", sourceObjective = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Aegis. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", progress = "Have your strikes into Zul'Gurub yielded success, {name}?  Only when you've brought me what I seek - and proven yourself fully to the tribe - will you earn a mantle second to none amongst the Zandalar.", completion = "Success... you are to be revered amongst the tribe, {name}.  It was no small feat acquiring the Paragons of Power needed for the mantle, but you handled it in the fashion of the deadliest of our predators.  You've earned your place amongst them, and you've certainly earned the right to wear their mantle.", sourceObjectiveStatus = "unverified-source-field" }
quests[8068] = { id = 8068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Illusionist's Mantle", description = "Magic is a raw, primal force to be shaped by those strong enough to do it.  Mojo is our extension of this power; one such potent manipulation of it is in the form of illusion.  How can one truly hope to win against a foe that is not even really there?  We Zandalar know the power of this, and as such illusionists hold a honored place within the tribe.\n\nTake the needed Paragons of Power from Zul'Gurub - for this, honor from the tribe and a powerful mantle used by our best illusionists will be yours!", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "How was your foray into Zul'Gurub?  Did you drive your enemies mad through the power of illusion?  Illusion or not, their deaths - and the Paragons of Power taken from them - will help thwart the rise of Hakkar.", completion = "Success!  You shall be honored in the tribe from here on!  Zul'Gurub has certainly tasted the might of the Zandalar today, thanks to you {name}.\n\nWith the tribe's blessing, take the Zandalar illusionist's mantle.  May it serve you well.", sourceObjectiveStatus = "unverified-source-field" }
quests[8069] = { id = 8069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Illusionist's Robes", description = "The tribe acknowledges station and power through what we wear.  Our vestments are made from the finest of materials, and interwoven with the mojo we use to make us powerful.  Illusionists are no exception; their robes are said to embody the essence of illusion in their look.  Legend states that their ancient robes never looked the same twice.\n\nI will give you an illusionist's robe, {name}... but earn your place of reverence among the tribe first!  Bring me the Paragons of Power from Zul'Gurub!", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Kossack. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "Have you returned with the Paragons of Power we need?  I know it will not be easy... but I have long predicted an outsider would come to aid us in our fight against Hakkar.  Let it be you, I say!", completion = "At last, someone worthy to wear the illusionist's robe!  Your success in Zul'Gurub has assured your reverences amongst the tribe for ages to come.  Wear it with pride, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8070] = { id = 8070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Confessor's Bindings", description = "Shortly after the fall of the Gurubashi, we Zandalar almost succumbed to a final defeat from evil within our own tribe.  It was then that the confessors amongst us arose, preserving the tribe by banishing out those who would destroy their own kind.  They not only keep us in tune with the spirits, but they also preserve the flesh.\n\nGo forth into Zul'Gurub and witness first hand the depravity of Hakkar and the Gurubashi.  Wrest the Paragons of Power that we seek from them; success will be rewarded!", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Sash. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "The Paragons of Power... do you have them?  Only when we have them will we be able to make use of the latent power stored inside them.  It will be good to turn the tables on the minions of the Blood God...", completion = "Success!  These will go a long way to building up our power against the rise of Hakkar.  With your help, we've taken a significant step in ensuring that the Blood God will not destroy us all.\n\nYou've earned honor with the tribe today, {name}.  Take this - the confessor's bindings - as a symbol of our thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[8071] = { id = 8071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Confessor's Mantle", description = "The confessors of the Zandalar all wear a distinctive mantle, marking them as the preservers of the tribe.  These mantles are woven with powerful mojo that aids them in judging those who would threaten our tribe.  As a priest, you too must spend your time judging those worthy and not; such a mantle would definitely be a blessing to you.\n\nIn exchange for fighting Hakkar's minions in Zul'Gurub and bringing me the Paragons of Power I seek, I will give you a mantle worthy of our finest confessors.", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Aegis. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "Do you have the Paragons of Power from Zul'Gurub?", completion = "Well done, {name} - the minions of Hakkar have surely felt the retribution of the Zandalar today, thanks to you.  Your actions have given you a permanent place of reverence within the tribe.  With our blessing, please take this confessor's mantle as your own!", sourceObjectiveStatus = "unverified-source-field" }
quests[8072] = { id = 8072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Madcap's Mantle", description = "One of Zandalar's legendary madcaps was Khar'vaxal the Cracked.  Legend states that when facing the enemies of the tribe for the first time, Kar'xavan used his mantle specifically woven with \"the weave of madness\".  His form was shrouded not only by the mantle, but also with the blinding speed of his twin daggers.  Madcaps today cherish their mantle as a sign of their place in the tribe.\n\nBring to me the Paragons of Power I seek, and such a mantle will be yours to weave madness unto your own enemies.", sourceObjective = "Bring Falthir the Sightless a Primal Hakkari Girdle. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", progress = "You've returned - do you have the Paragons of Power I need?\n\nThe legend of Khar'vaxal the Cracked serves us today as a reminder that no foe - no matter how great a threat they may be - is impossible to overcome.  Chaos will bring everyone to their knees, that much is certain... and perhaps the most non-chaotic elements of chaos.", completion = "Victory is ours this day, thanks to the madness you have sowed upon our mutual enemies!  You are to be honored amongst the Zandalar, and there is no better way of showing gratitude for your deeds than by offering you the madcap's mantle!", sourceObjectiveStatus = "unverified-source-field" }
quests[8073] = { id = 8073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Madcap's Tunic", description = "My eyes failed me long ago, but I do not miss them.  Even in a tribe such as ours - where one's vestments convey station and purpose - the most potent of garb exudes power that simple eyes cannot see.  The prized tunic of the Zandalar madcap is no exception, exuding the raw power of chaos and madness that they are able to channel.\n\nThe Paragons of Power I need lie in Zul'Gurub; bring me what I seek, and I will reward you with your own legendary tunic... one befitting a weaver of madness.", sourceObjective = "Bring Falthir the Sightless a Primal Hakkari Aegis. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", progress = "Welcome back to the Isle, {name}... have you returned triumphantly with the Paragons of Power in tow?", completion = "Impressive... you have accomplished today what few thought was possible.  Your reverence in the tribe is assured for a lifetime, {name}.  You have earned the right to don the madcap's tunic - do so with our blessing.", sourceObjectiveStatus = "unverified-source-field" }
quests[8074] = { id = 8074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Augur's Belt", description = "Augurs know the mojo of the elements, mon.  They use it as a means to guide the tribe to glory.  In the dark days after the Gurubashi Empire ripped itself up, our augurs led us to our safe haven in the South Seas.  They've also led us back here to the Vale, right back to the heart of evil brewin' in Zul'Gurub.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do it and I'll give ya a belt that our augurs use - one with powerful mojo inside it!", sourceObjective = "Bring Maywiki of Zuldazar a Primal Hakkari Girdle. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.", progress = "The Paragons of Power are what I need mon - we'll tap the power right out of them in our fight against the evil from Zul'Gurub.  Do ya have them for me?", completion = "I can smell the scent of vanquished evil on ya, {name}.  It's a sweet smell mon... one I think you know quite well.\n\nI know it's no small feat to have brought me the Paragons of Power required for the belt.  Your deeds have not only honored the tribe, but also honored yourself amongst my tribe.  Here ya are - take the augur's belt and don it as your own!", sourceObjectiveStatus = "unverified-source-field" }
quests[8075] = { id = 8075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Augur's Hauberk", description = "The augurs of the Zandalar all wear a distinctive chest piece called a hauberk.  It's fitted with the finest of silks and cloths, interwoven with strong chain.  It's a symbol of not only their divinity, but also of their authority, mon.  It's never wise to cross one whose life is devoted to speakin' with the spirits...\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do it and I'll give ya one of the finest hauberks our augurs would ever hope to wear!", sourceObjective = "Bring Maywiki of Zuldazar a Primal Hakkari Tabard. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.", progress = "The Paragons of Power are a key source of magic power - the same kind of power that goes into makin' the augur's hauberk.  Bring me what I need, and I'll be able to share the finest of vestments any Zandalar augur would be wantin' as their own.", completion = "I know what ya had to go through to bring me the Paragons of Power, {name}.  It wasn't easy, mon - defeatin' the evil that seeps out of Zul'Gurub like a foul ooze - but now that it is all said and done, I can easily say that you'll be revered amongst the Zandalar for ages to come!\n\nHere - take the augur's hauberk and wear it with pride!", sourceObjectiveStatus = "unverified-source-field" }
quests[8076] = { id = 8076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Demoniac's Mantle", description = "The demoniac seeks to embody power outright, not just possess it.  More than one of our demoniacs has lost a fight with a demon; with our enemies threatening us - especially in Zul'Gurub - the power that a demoniac is able to unleash on our foes is worth the sacrifice.  Our survival depends on crushing those who would destroy us; the fall of the Gurubashi Empire taught us this.\n\nTravel to Zul'Gurub and gain the Paragons of Power we need.  Do this, and a valuable demoniac item shall be yours.", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Sash. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "Retrieved the Paragons of Power from Zul'Gurub?  While we will take the latent power from these items and make them our own, we will give you your own reward of power should you be successful...", completion = "Well done, {name}.  The Paragons of Power from Zul'Gurub should act as a reminder of wasted power.  The Gurubashi were strong at their height, but they allowed themselves to be consumed by it.  A demoniac knows that the game they play is much similar, but the power unleashed is often the very thing needed for survival.\n\nUse this mantle as an honored ally of the Zandalar... it will serve you well.", sourceObjectiveStatus = "unverified-source-field" }
quests[8077] = { id = 8077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Demoniac's Robes", description = "The ultimate symbol of power amongst the tribe is the garb we wear in battle.  A demoniac's robes have fused fine runecloth and devastatingly powerful mojo into a single fabric.  The visage of the robe is said to instill fear into the minds of all who see it... especially the demons that the demoniac will eventually dominate.\n\nFrom Zul'Gurub, you must bring me a very specific set of the Paragons of Power.  It will be difficult... but your success will assure you of acquiring a robe for yourself.", sourceObjective = "Bring Al'tabim the All-Seeing a Primal Hakkari Kossack. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", progress = "The Paragons of Power... you have returned with them?  Only once we have them will we share the ultimate symbol of demoniac power with you, {name}.", completion = "Impressive - your victory in Zul'Gurub has assured us - nay, the world - that Hakkar will not prevail.  The time may come when you face the Blood God directly... and should this come to pass know that your reverence is assured amongst the Zandalar tribe.\n\nOh, and this simple robe should help out too I think.\n\n<Al'tabim winks knowingly at you.>", sourceObjectiveStatus = "unverified-source-field" }
quests[8078] = { id = 8078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Vindicator's Belt", description = "The ultimate vengeance waits within Zul'Gurub.  Hakkar must not rise again.  Hakkar destroyed the Gurubashi Empire from within.  No sacrifice was enough.  The trolls are a shadow of former glories.  I know this is because of Hakkar.\n\nBecome the vindicator you were meant to be.  Wreak havoc on the minions of evil.  Zul'Gurub must taste Zandalar vengeance.  Bring me proof in the Paragons of Power.  You will receive the vindicator's belt.  You will receive real power.\n\nGo.", sourceObjective = "Bring Jin'rokh the Breaker a Primal Hakkari Girdle. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", progress = "Have you brought the Paragons of Power?  Have you struck down the enemies of the tribe?  Hakkar must know the wrath of the vindicator!", completion = "The way of the vindicator is now known to you.  You have brought honor to the tribe.  You have brought honor to yourself.  You have brought pain to our enemies.\n\nThe vindicator's belt is yours.  You are surely becoming one with the way of the vindicator.", sourceObjectiveStatus = "unverified-source-field" }
quests[8079] = { id = 8079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragons of Power: The Vindicator's Breastplate", description = "The vindicator's symbol of power is the breastplate.  It is forged with powerful mojo.  It is trusted only to those we revere.  It is the Zandalar symbol of vengeance.\n\nTo become a vindicator is to become vengeance.  Take the Paragons of Power we need from Zul'Gurub.  Bring them to us.  We will take the mojo stolen from us.  We will make the minions of Hakkar pay.  We will reward you with the vindicator's breastplate.\n\nGo.  Be our vengeance, {name}.", sourceObjective = "Bring Jin'rokh the Breaker a Primal Hakkari Kossack. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", progress = "Your presence means victory?  Do you have the Paragons of Power?  Tell me of the vengeance you have wrought today!", completion = "You are to be revered for your deeds.  The tribe rewards its heroes.  Zul'Gurub has tasted Zandalar vengeance like never before.\n\nYour deeds will herald the deeds of others to come.  They will look upon you as a sign of real power.  They will look upon you as vengeance personified!", sourceObjectiveStatus = "unverified-source-field" }
quests[8080] = { id = 8080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Basin Resources!", description = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, {name}.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.", sourceObjective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.", sourceObjectiveStatus = "unverified-source-field" }
quests[8101] = { id = 8101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pebble of Kajaro", sourceObjective = "{race}, the pebble held within the frame of this talisman comes from Mount Kajaro in the South Seas. Mount Kajaro is an area plagued by volatility - marked by violent and oftentimes magical volcanic eruptions.\n\nAs your bond with the trolls of Zandalar grows, so too shall the power of this pebble. Harness the power of the pebble to strike down our enemies. Be like the mountain: Quick, explosive, deadly...", sourceObjectiveStatus = "unverified-source-field" }
quests[8102] = { id = 8102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pebble of Kajaro", progress = "Welcome back, {class}. I can see that the pebble has seen much use. Many of our foes have fallen to your otherworldly abilities. Their suffering has been great. It is time that I enhance the power of the pebble. Give it to me.", completion = "Be unstoppable, like the molten fronts of Kajaro." }
quests[8103] = { id = 8103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pebble of Kajaro", progress = "Hakkari fear you, {name}. They speak of horrors they believed that only their faceless God could perpetrate. You have burned them with the force of Kajaro. They now know fear in two places.\n\nIt is time to further strengthen the pebble. Hand me the talisman.", completion = "Continue in your decimation of the trolls of Zul'Gurub. Hakkar must see that the world will not buckle beneath his indomitable will." }
quests[8104] = { id = 8104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jewel of Kajaro", progress = "Give me the talisman, {name}. I must show you something.", completion = "<Al'tabim shatters the pebble with a powerful unseen force.>\n\nDo you see? The pebble is what we call a geode. Inside the pebble are powerful crystals that have been soaking in the latent energies from our world. By cutting the pebble in half, I have finally allowed its full potential to be realized. Use it to lay waste to our enemies." }
